#!/usr/bin/env bash\nset -euo pipefail\nROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"\nINDEX="$ROOT/frontend/wrapper-ui/apc-wrapper-local/index.html"\nBRIDGE="$ROOT/frontend/wrapper-ui/apc-wrapper-local/privatepages/companion-local-anki-bridge.js"\nDOC="$ROOT/docs/stage-17k-v-companion-anki-consented-current-card-handoff.md"\ntest -f "$INDEX"\ntest -f "$BRIDGE"\ntest -f "$DOC"\ngrep -Fq "stage17kv-companion-anki-consented-current-card-handoff-20260628" "$INDEX"\ngrep -Fq "stage17kv-companion-anki-consented-current-card-handoff-20260628" "$BRIDGE"\ngrep -Fq "function consentedCurrentAnkiCardForStudyCommand(consented)" "$BRIDGE"\ngrep -Fq "command: \"consented_current_anki_card_for_study\"" "$BRIDGE"\ngrep -Fq "consentedCurrentAnkiCardForStudyCommand: consentedCurrentAnkiCardForStudyCommand" "$BRIDGE"\ngrep -Fq "data-local-anki-bridge-action=\"consent-current-card\"" "$BRIDGE"\ngrep -Fq "Use current Anki card in Companion study" "$BRIDGE"\ngrep -Fq "card_text_persisted: false" "$BRIDGE"\ngrep -Fq "backend_calls_allowed: false" "$BRIDGE"\ngrep -Fq "model_calls_allowed: false" "$BRIDGE"\ngrep -Fq "anki_write_allowed: false" "$BRIDGE"\ngrep -Fq "mydecks_writeback_allowed: false" "$BRIDGE"\nif grep -Eq "fetch\(|XMLHttpRequest|sendBeacon|localStorage\.setItem" "$BRIDGE"; then echo "forbidden network/persistence marker"; exit 1; fi\ngrep -Fq 'Stage 17K-V' "$DOC"\ngrep -Fq 'consentedCurrentAnkiCardForStudyCommand' "$DOC"\ngrep -Fq 'Use current Anki card in Companion study' "$DOC"\ngrep -Fq 'consented: false' "$DOC"\ngrep -Fq 'consented: true' "$DOC"\ngrep -Fq 'card_text_persisted: false' "$DOC"\ngrep -Fq 'No backend deploy, DB write, Anki write' "$DOC"\ngrep -Fq 'No Anki question text or answer text is saved to repo docs' "$DOC"\nif command -v node >/dev/null 2>&1; then node --check "$BRIDGE"; fi\necho "PASS: Stage 17K-V Companion Anki consented current-card handoff smoke passed"\n